/**
 * FAQ Tab Switching
 * Handles tab switching functionality for the FAQ page
 */

(function() {
  'use strict';

  // DOMContentLoaded event handler
  function initFaqTabs() {
    const tabButtons = document.querySelectorAll('.faq-tab');
    const tabPanels = document.querySelectorAll('.faq-panel');

    /**
     * Switch to a specific tab
     * @param {string} tabName - The data-tab value of the tab to activate
     */
    function switchTab(tabName) {
      // Deactivate all tabs and panels
      tabButtons.forEach((btn) => {
        btn.classList.remove('is-active');
        btn.setAttribute('aria-selected', 'false');
      });
      tabPanels.forEach((panel) => {
        panel.classList.remove('is-active');
      });

      // Activate the selected tab and panel
      const activeTab = document.querySelector(`[data-tab="${tabName}"]`);
      const activePanel = document.getElementById(`faq-${tabName}`);

      if (activeTab) {
        activeTab.classList.add('is-active');
        activeTab.setAttribute('aria-selected', 'true');
        activeTab.focus();
      }

      if (activePanel) {
        activePanel.classList.add('is-active');
      }

      // Save the active tab to localStorage for persistence
      try {
        localStorage.setItem('faq-active-tab', tabName);
      } catch (e) {
        // Silently fail if localStorage is not available
      }
    }

    // Add click event listeners to tab buttons
    tabButtons.forEach((btn) => {
      btn.addEventListener('click', function() {
        const tabName = this.getAttribute('data-tab');
        switchTab(tabName);
      });

      // Add keyboard navigation (arrow keys)
      btn.addEventListener('keydown', function(e) {
        let nextTab = null;

        if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
          e.preventDefault();
          const currentIndex = Array.from(tabButtons).indexOf(this);
          nextTab = currentIndex > 0 ? tabButtons[currentIndex - 1] : tabButtons[tabButtons.length - 1];
        } else if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
          e.preventDefault();
          const currentIndex = Array.from(tabButtons).indexOf(this);
          nextTab = currentIndex < tabButtons.length - 1 ? tabButtons[currentIndex + 1] : tabButtons[0];
        } else if (e.key === 'Home') {
          e.preventDefault();
          nextTab = tabButtons[0];
        } else if (e.key === 'End') {
          e.preventDefault();
          nextTab = tabButtons[tabButtons.length - 1];
        }

        if (nextTab) {
          const tabName = nextTab.getAttribute('data-tab');
          switchTab(tabName);
        }
      });
    });

    // Restore the last active tab from localStorage
    try {
      const savedTab = localStorage.getItem('faq-active-tab');
      if (savedTab) {
        switchTab(savedTab);
      }
    } catch (e) {
      // Silently fail if localStorage is not available
    }
  }

  // Run initialization when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initFaqTabs);
  } else {
    initFaqTabs();
  }
})();

/**
 * FAQ Details Smooth Animation
 * Adds smooth open/close animation to details elements
 */

(function() {
  'use strict';

  function initDetailsAnimation() {
    const details = document.querySelectorAll('.faq-item');

    details.forEach((detail) => {
      const summary = detail.querySelector('.faq-q');
      const content = detail.querySelector('.faq-answer');

      if (!summary || !content) return;

      // Prevent default details animation for custom animation
      summary.addEventListener('click', function(e) {
        // Prevent the default toggle behavior
        e.preventDefault();

        // Toggle the open attribute
        if (detail.open) {
          detail.open = false;
        } else {
          detail.open = true;
        }
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initDetailsAnimation);
  } else {
    initDetailsAnimation();
  }
})();
